pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newImplementation) public {
        vm.assume(newImplementation != address(0));

        c.updateRoundImplementation(payable(newImplementation));

        assertTrue(c.roundImplementation() != address(0));
